"""Tests for the no-show pattern analysis pipeline."""
import numpy as np
import pytest

from gen import generate, SEED, N
from analyze import analyze, BUCKETS


@pytest.fixture(scope="module")
def data():
    return generate()


@pytest.fixture(scope="module")
def res(data):
    return analyze(data)


def test_dataset_shape(data):
    assert len(data["no_show"]) == N == 5000
    assert data["weekday"].min() >= 0 and data["weekday"].max() <= 6
    assert data["lead_time_days"].min() >= 0 and data["lead_time_days"].max() <= 30


def test_monday_excess(res):
    """Monday's rate exceeds Tue-Fri mean by ~0.04 (planted effect)."""
    monday = res["weekday_rates"][0]
    tue_fri_mean = float(np.mean(res["weekday_rates"][1:5]))
    excess = monday - tue_fri_mean
    assert 0.025 < excess < 0.055


def test_bucket_rates_monotone_increasing(res):
    rates = res["bucket_rates"]
    assert all(np.isfinite(rates))
    assert rates[0] < rates[1] < rates[2]


def test_slope_recovers_planted_value(res):
    """Recovered slope is within 0.002 of the planted 0.006 per day."""
    assert abs(res["slope"] - 0.006) < 0.002


def test_all_rates_valid_probabilities(res):
    for rate in res["bucket_rates"] + res["weekday_rates"]:
        assert 0.0 <= rate <= 1.0
    for row in res["advice"]:
        assert 0.0 <= row["rate"] <= 1.0


def test_overbooking_advice_reconciliation(res):
    """Extra slots for the worst cell = round(rate * slots) and it matches advice."""
    wc = res["worst_cell"]
    expected_extra = round(wc["rate"] * wc["slots"])
    assert wc["extra_slots"] == expected_extra
    # The worst cell must be the maximum-rate cell in the advice table.
    best = max(res["advice"], key=lambda r: r["rate"])
    assert (best["weekday"], best["bucket"]) == (wc["weekday"], wc["bucket"])
    assert wc["extra_slots"] > 0

